import json
from collections import Counter

with open('Answers/results/0624_Wed_0900.json', 'r', encoding='utf-8') as f:
    tasks = json.load(f)

from_names = Counter()
text_fields = Counter()
example = None
for task in tasks:
    for ann in task.get('annotations', []):
        email = ((ann.get('completed_by') or {}).get('email') or '').lower()
        if email != 'nitzan.gour@gmail.com':
            continue
        for res in ann.get('result', []):
            fn = res.get('from_name', '')
            from_names[fn] += 1
            val = res.get('value') or {}
            if 'text' in val and val.get('text'):
                text_fields[fn] += 1
                if example is None:
                    example = (task.get('data', {}).get('record_id',''), fn, val.get('text'))

print('from_name counts:')
for k,v in from_names.most_common():
    print(k, v)
print('\ntext-bearing fields:')
for k,v in text_fields.items():
    print(k, v)
print('\nexample text field:', example)
